39	/**
40	 * Util class for HFile reading and writing in Hudi
41	 */
42	public class HoodieHFileUtils {
43	  // Based on HBase 2.4.9, the primaryReplicaReader is mainly used for constructing
44	  // block cache key, so if we do not use block cache then it is OK to set it as any
45	  // value. We use true here.
46	  private static final boolean USE_PRIMARY_REPLICA_READER = true;
47	
48	  /**
49	   * Creates HFile reader for a file with default `primaryReplicaReader` as true.
50	   *
51	   * @param fs            File system.
52	   * @param path          Path to file to read.
53	   * @param cacheConfig   Cache configuration.
54	   * @param configuration Configuration
55	   * @return HFile reader
56	   * @throws IOException Upon error.
57	   */
58	  public static HFile.Reader createHFileReader(
59	      FileSystem fs, Path path, CacheConfig cacheConfig, Configuration configuration) {
60	    try {
61	      return HFile.createReader(fs, path, cacheConfig, USE_PRIMARY_REPLICA_READER, configuration);
62	    } catch (IOException e) {
63	      throw new HoodieIOException("Failed to initialize HFile reader for  " + path, e);
64	    }
65	  }
66	
67	  /**
68	   * Creates HFile reader for a file with default `primaryReplicaReader` as true.
69	   *
70	   * @param storage       {@link HoodieStorage} instance.
71	   * @param path          path of file to read.
72	   * @param cacheConfig   Cache configuration.
73	   * @param configuration Configuration
74	   * @return HFile reader
75	   * @throws IOException Upon error.
76	   */
77	  public static HFile.Reader createHFileReader(
78	      HoodieStorage storage, StoragePath path, CacheConfig cacheConfig, Configuration configuration) {
79	    try {
80	      return HFile.createReader((FileSystem) storage.getFileSystem(),
81	          new Path(path.toUri()), cacheConfig, USE_PRIMARY_REPLICA_READER, configuration);
82	    } catch (IOException e) {
83	      throw new HoodieIOException("Failed to initialize HFile reader for  " + path, e);
84	    }
85	  }
86	
87	  /**
88	   * Creates HFile reader for byte array with default `primaryReplicaReader` as true.
89	   *
90	   * @param storage       {@link HoodieStorage} instance.
91	   * @param dummyPath Dummy path to file to read.
92	   * @param content       Content in byte array.
93	   * @return HFile reader
94	   * @throws IOException Upon error.
95	   */
96	  public static HFile.Reader createHFileReader(
97	      HoodieStorage storage, StoragePath dummyPath, byte[] content) {
98	    // Avoid loading default configs, from the FS, since this configuration is mostly
99	    // used as a stub to initialize HFile reader
100	    Configuration conf = new Configuration(false);
101	    HoodieHBaseAvroHFileReader.SeekableByteArrayInputStream bis =
102	        new HoodieHBaseAvroHFileReader.SeekableByteArrayInputStream(content);
103	    FSDataInputStream fsdis = new FSDataInputStream(bis);
104	    FSDataInputStreamWrapper stream = new FSDataInputStreamWrapper(fsdis);
105	    ReaderContext context = new ReaderContextBuilder()
106	        .withFilePath(new Path(dummyPath.toUri()))
107	        .withInputStreamWrapper(stream)
108	        .withFileSize(content.length)
109	        .withFileSystem((FileSystem) storage.getFileSystem())
110	        .withPrimaryReplicaReader(USE_PRIMARY_REPLICA_READER)
111	        .withReaderType(ReaderContext.ReaderType.STREAM)
112	        .build();
113	    try {
114	      HFileInfo fileInfo = new HFileInfo(context, conf);
115	      HFile.Reader reader = HFile.createReader(context, fileInfo, new CacheConfig(conf), conf);
116	      fileInfo.initMetaAndIndex(reader);
117	      return reader;
118	    } catch (IOException e) {
119	      throw new HoodieIOException("Failed to initialize HFile reader for  " + dummyPath, e);
120	    }
121	  }
122	}
